# ============================================================
# Language scoping (simplified, regex-based approximations)
# ============================================================

def get_language_scope_ranges(content: str, lang: str, query_value: str) -> List[Tuple[int,int]]:
    """Get byte ranges in content that are in scope for the given language scope."""
    # Returns list of (start, end) byte ranges (absolute positions in content)
    lang_lower = lang.lower()

    if lang_lower == 'python':
        return _python_scope(content, query_value)
    elif lang_lower == 'rust':
        return _rust_scope(content, query_value)
    elif lang_lower == 'go':
        return _go_scope(content, query_value)
    elif lang_lower == 'typescript':
        return _typescript_scope(content, query_value)
    elif lang_lower == 'c':
        return _c_scope(content, query_value)
    elif lang_lower == 'csharp':
        return _csharp_scope(content, query_value)
    elif lang_lower == 'hcl':
        return _hcl_scope(content, query_value)
    return []

def _line_ranges(content: str, line_start: int, line_end: int) -> List[Tuple[int,int]]:
    """Get byte ranges for lines [line_start, line_end) (0-indexed)."""
    lines = content.split('\n')
    ranges = []
    offset = 0
    for i, line in enumerate(lines):
        line_len = len(line)
        if i >= line_start and i < line_end:
            ranges.append((offset, offset + line_len))
        offset += line_len + 1
    return ranges

def _find_indented_block(content: str, start_line: int) -> int:
    """Find the end line (exclusive) of an indented block starting after start_line."""
    lines = content.split('\n')
    if start_line >= len(lines):
        return start_line + 1
    # Find indent of first non-empty line after start_line
    base_indent = None
    for i in range(start_line + 1, len(lines)):
        stripped = lines[i]
        if stripped.strip():
            indent = len(stripped) - len(stripped.lstrip())
            base_indent = indent
            break
    if base_indent is None or base_indent == 0:
        return start_line + 1

    # Find end of block
    end = start_line + 1
    for i in range(start_line + 1, len(lines)):
        if lines[i].strip() == '':
            end = i + 1
            continue
        indent = len(lines[i]) - len(lines[i].lstrip())
        if indent >= base_indent:
            end = i + 1
        else:
            break
    return end

def _python_scope(content: str, scope: str) -> List[Tuple[int,int]]:
    lines = content.split('\n')
    ranges = []

    if scope == 'comments':
        # Python comment lines: # to end of line
        offset = 0
        for line in lines:
            idx = line.find('#')
            # Make sure '#' is not inside a string (simplified)
            if idx >= 0:
                ranges.append((offset + idx, offset + len(line)))
            offset += len(line) + 1
        return ranges

    elif scope == 'strings':
        # Find string literals (simplified: match quoted strings)
        return _find_python_strings(content)

    elif scope == 'doc-strings':
        return _find_python_docstrings(content)

    elif scope == 'imports':
        # Module names in import statements
        return _find_python_imports(content)

    elif scope in ('class', 'def', 'async-def', 'methods', 'class-methods',
                   'static-methods', 'with', 'try', 'lambda', 'globals',
                   'variable-identifiers', 'types', 'identifiers',
                   'function-names', 'function-calls'):
        return _find_python_block(content, scope)

    return []

def _find_python_strings(content: str) -> List[Tuple[int,int]]:
    """Find string literal content (inside quotes) in Python."""
    ranges = []
    i = 0
    n = len(content)
    while i < n:
        # Triple quote
        if content[i:i+3] in ('"""', "'''"):
            quote = content[i:i+3]
            start = i + 3
            end = content.find(quote, start)
            if end == -1:
                break
            ranges.append((start, end))
            i = end + 3
        elif content[i] in ('"', "'"):
            quote = content[i]
            start = i + 1
            j = start
            while j < n:
                if content[j] == '\\':
                    j += 2
                elif content[j] == quote:
                    break
                else:
                    j += 1
            ranges.append((start, j))
            i = j + 1
        elif content[i] == '#':
            # Skip to end of line
            while i < n and content[i] != '\n':
                i += 1
        else:
            i += 1
    return ranges

def _find_python_docstrings(content: str) -> List[Tuple[int,int]]:
    """Find docstring content in Python functions/classes."""
    ranges = []
    # Find triple-quoted strings that appear right after def/class
    lines = content.split('\n')
    offset = 0
    offsets = []
    for line in lines:
        offsets.append(offset)
        offset += len(line) + 1

    i = 0
    while i < len(lines):
        line = lines[i].strip()
        if line.startswith('def ') or line.startswith('async def ') or line.startswith('class '):
            # Look for docstring in next non-empty lines
            j = i + 1
            while j < len(lines) and lines[j].strip() == '':
                j += 1
            if j < len(lines):
                stripped = lines[j].strip()
                if stripped.startswith('"""') or stripped.startswith("'''"):
                    quote = stripped[:3]
                    # Find the string content
                    full_line = lines[j]
                    q_start = full_line.find(quote) + 3
                    abs_start = offsets[j] + q_start
                    # Find end
                    rest = full_line[q_start:]
                    end_in_rest = rest.find(quote)
                    if end_in_rest >= 0:
                        ranges.append((abs_start, abs_start + end_in_rest))
                    else:
                        # Multi-line docstring
                        full = content[abs_start:]
                        end_pos = full.find(quote)
                        if end_pos >= 0:
                            ranges.append((abs_start, abs_start + end_pos))
        i += 1
    return ranges

def _find_python_imports(content: str) -> List[Tuple[int,int]]:
    """Find module names in import statements."""
    ranges = []
    offset = 0
    for line in content.split('\n'):
        # import foo.bar.baz -> match "foo.bar.baz"
        m = re.match(r'^import\s+(.+?)(?:\s+as\s+\w+)?\s*$', line)
        if m:
            start = line.index(m.group(1))
            ranges.append((offset + start, offset + start + len(m.group(1))))
        # from foo.bar import baz -> match "foo.bar"
        m2 = re.match(r'^from\s+(\S+)\s+import', line)
        if m2:
            start = line.index(m2.group(1), 5)  # after 'from '
            ranges.append((offset + start, offset + start + len(m2.group(1))))
        offset += len(line) + 1
    return ranges

def _find_python_block(content: str, scope: str) -> List[Tuple[int,int]]:
    """Find blocks of given scope type in Python."""
    lines = content.split('\n')
    ranges = []

    # Compute line offsets
    offsets = []
    off = 0
    for line in lines:
        offsets.append(off)
        off += len(line) + 1

    if scope == 'class':
        for i, line in enumerate(lines):
            if re.match(r'^\s*class\s+\w', line):
                end = _find_indented_block(content, i)
                for j in range(i, end):
                    if j < len(lines):
                        ranges.append((offsets[j], offsets[j] + len(lines[j])))

    elif scope in ('def', 'async-def'):
        for i, line in enumerate(lines):
            stripped = line.lstrip()
            is_async = stripped.startswith('async def ')
            is_def = stripped.startswith('def ')
            if scope == 'def' and (is_def or is_async):
                end = _find_indented_block(content, i)
                for j in range(i, end):
                    if j < len(lines):
                        ranges.append((offsets[j], offsets[j] + len(lines[j])))
            elif scope == 'async-def' and is_async:
                end = _find_indented_block(content, i)
                for j in range(i, end):
                    if j < len(lines):
                        ranges.append((offsets[j], offsets[j] + len(lines[j])))

    elif scope == 'methods':
        # Functions inside class bodies
        in_class = False
        class_indent = -1
        for i, line in enumerate(lines):
            stripped = line.lstrip()
            indent = len(line) - len(stripped)
            if re.match(r'class\s+\w', stripped):
                in_class = True
                class_indent = indent
            elif in_class and indent <= class_indent and stripped and not stripped.startswith('#'):
                in_class = False
            if in_class and re.match(r'def\s+\w|async\s+def\s+\w', stripped) and indent > class_indent:
                end = _find_indented_block(content, i)
                for j in range(i, end):
                    if j < len(lines):
                        ranges.append((offsets[j], offsets[j] + len(lines[j])))

    elif scope in ('with', 'try', 'lambda'):
        kw = scope
        for i, line in enumerate(lines):
            stripped = line.lstrip()
            if stripped.startswith(kw + ' ') or stripped.startswith(kw + ':'):
                end = _find_indented_block(content, i)
                for j in range(i, end):
                    if j < len(lines):
                        ranges.append((offsets[j], offsets[j] + len(lines[j])))

    elif scope == 'globals':
        for i, line in enumerate(lines):
            # Module-level assignments (no indentation)
            if re.match(r'^[a-zA-Z_]\w*\s*=', line):
                ranges.append((offsets[i], offsets[i] + len(line)))

    elif scope == 'function-names':
        offset = 0
        for line in content.split('\n'):
            m = re.match(r'^(\s*(?:async\s+)?def\s+)(\w+)', line)
            if m:
                start = m.start(2)
                ranges.append((offset + start, offset + start + len(m.group(2))))
            offset += len(line) + 1

    elif scope == 'function-calls':
        offset = 0
        for line in content.split('\n'):
            for m in re.finditer(r'\b(\w+)\s*\(', line):
                start = m.start(1)
                ranges.append((offset + start, offset + start + len(m.group(1))))
            offset += len(line) + 1

    elif scope == 'identifiers':
        offset = 0
        for line in content.split('\n'):
            for m in re.finditer(r'\b[a-zA-Z_]\w*\b', line):
                ranges.append((offset + m.start(), offset + m.end()))
            offset += len(line) + 1

    return ranges

def _rust_scope(content: str, scope: str) -> List[Tuple[int,int]]:
    lines = content.split('\n')
    ranges = []
    offsets = []
    off = 0
    for line in lines:
        offsets.append(off)
        off += len(line) + 1

    if scope == 'comments':
        for i, line in enumerate(lines):
            # Line comments // but not ///
            idx = line.find('//')
            if idx >= 0 and not line[idx:idx+3] == '///':
                ranges.append((offsets[i] + idx, offsets[i] + len(line)))
        return ranges

    elif scope == 'doc-comments':
        for i, line in enumerate(lines):
            idx = line.find('///')
            if idx >= 0:
                ranges.append((offsets[i] + idx, offsets[i] + len(line)))
        return ranges

    elif scope == 'strings':
        return _find_rust_strings(content)

    elif scope == 'uses':
        for i, line in enumerate(lines):
            m = re.match(r'^use\s+(.+?);', line)
            if m:
                start = line.index(m.group(1))
                ranges.append((offsets[i] + start, offsets[i] + start + len(m.group(1))))
        return ranges

    elif scope == 'attribute':
        for i, line in enumerate(lines):
            m = re.match(r'^(\s*)(#\[.+?\])', line)
            if m:
                start = m.start(2)
                ranges.append((offsets[i] + start, offsets[i] + start + len(m.group(2))))
        return ranges

    elif scope in ('fn', 'impl-fn', 'priv-fn', 'pub-fn', 'pub-crate-fn',
                   'const-fn', 'async-fn', 'unsafe-fn', 'extern-fn', 'test-fn',
                   'pub-self-fn', 'pub-super-fn') or scope.startswith('fn~'):
        return _rust_find_fn(content, scope, lines, offsets)

    elif scope in ('struct', 'priv-struct', 'pub-struct', 'pub-crate-struct',
                   'pub-self-struct', 'pub-super-struct') or scope.startswith('struct~'):
        return _rust_find_struct(content, scope, lines, offsets)

    elif scope in ('enum', 'priv-enum', 'pub-enum', 'pub-crate-enum',
                   'pub-self-enum', 'pub-super-enum') or scope.startswith('enum~'):
        return _rust_find_enum(content, scope, lines, offsets)

    elif scope in ('trait',) or scope.startswith('trait~'):
        return _rust_find_block(content, 'trait', scope, lines, offsets)

    elif scope in ('impl', 'impl-type', 'impl-trait'):
        return _rust_find_impl(content, scope, lines, offsets)

    elif scope in ('mod',) or scope.startswith('mod~') or scope == 'mod-tests':
        return _rust_find_block(content, 'mod', scope, lines, offsets)

    elif scope == 'enum-variant':
        return _rust_find_enum_variants(content, lines, offsets)

    elif scope in ('type-def',):
        r1 = _rust_find_struct(content, 'struct', lines, offsets)
        r2 = _rust_find_enum(content, 'enum', lines, offsets)
        return r1 + r2

    elif scope in ('identifier', 'type-identifier'):
        offset = 0
        for line in content.split('\n'):
            for m in re.finditer(r'\b[a-zA-Z_]\w*\b', line):
                ranges.append((offset + m.start(), offset + m.end()))
            offset += len(line) + 1
        return ranges

    elif scope == 'closure':
        offset = 0
        for line in content.split('\n'):
            for m in re.finditer(r'\|[^|]*\|', line):
                ranges.append((offset + m.start(), offset + m.end()))
            offset += len(line) + 1
        return ranges

    elif scope == 'unsafe':
        return _rust_find_unsafe(content, lines, offsets)

    return []

def _rust_find_brace_block(content: str, start_line: int, lines: list, offsets: list) -> int:
    """Find end line of a brace-delimited block starting from start_line."""
    depth = 0
    for i in range(start_line, len(lines)):
        for c in lines[i]:
            if c == '{': depth += 1
            elif c == '}':
                depth -= 1
                if depth == 0:
                    return i + 1
    return len(lines)

def _rust_find_fn(content, scope, lines, offsets):
    ranges = []
    name_filter = None
    if scope.startswith('fn~'):
        name_filter = scope[3:]

    for i, line in enumerate(lines):
        stripped = line.lstrip()
        # Match fn declarations
        m = re.match(r'((?:pub(?:\([^)]*\))?\s+)?(?:async\s+)?(?:const\s+)?(?:unsafe\s+)?(?:extern\s*(?:"[^"]*"\s+)?)?fn\s+)(\w+)', stripped)
        if m:
            fn_name = m.group(2)
            vis = m.group(1)

            if name_filter and not re.search(name_filter, fn_name):
                continue

            if scope == 'priv-fn' and ('pub' in vis or 'pub(' in vis):
                continue
            if scope == 'pub-fn' and not re.match(r'pub\s+fn|pub\s+async', vis) and not 'pub fn' in vis:
                # more careful check
                if not vis.strip().startswith('pub ') and not vis.strip() == 'pub':
                    continue
            if scope == 'const-fn' and 'const' not in vis:
                continue
            if scope == 'async-fn' and 'async' not in vis:
                continue
            if scope == 'unsafe-fn' and 'unsafe' not in vis:
                continue
            if scope == 'extern-fn' and 'extern' not in vis:
                continue
            if scope == 'test-fn':
                # Check preceding attributes for #[test] or similar
                has_test = False
                for k in range(max(0, i-3), i):
                    if 'test' in lines[k]:
                        has_test = True
                        break
                if not has_test:
                    continue
            if scope == 'impl-fn':
                # Must be inside an impl block - simplified check
                pass

            end = _rust_find_brace_block(content, i, lines, offsets)
            for j in range(i, end):
                if j < len(lines):
                    ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

def _rust_find_struct(content, scope, lines, offsets):
    ranges = []
    name_filter = None
    if isinstance(scope, str) and scope.startswith('struct~'):
        name_filter = scope[7:]

    for i, line in enumerate(lines):
        stripped = line.lstrip()
        m = re.match(r'((?:pub(?:\([^)]*\))?\s+)?struct\s+)(\w+)', stripped)
        if m:
            struct_name = m.group(2)
            if name_filter and not re.search(name_filter, struct_name):
                continue
            # Check if this is a tuple struct (ends with ;) or block struct
            if '{' in line:
                end = _rust_find_brace_block(content, i, lines, offsets)
            else:
                end = i + 1
                for j in range(i, len(lines)):
                    if ';' in lines[j]:
                        end = j + 1
                        break
            for j in range(i, end):
                if j < len(lines):
                    ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

def _rust_find_enum(content, scope, lines, offsets):
    ranges = []
    name_filter = None
    if isinstance(scope, str) and scope.startswith('enum~'):
        name_filter = scope[5:]

    for i, line in enumerate(lines):
        stripped = line.lstrip()
        m = re.match(r'((?:pub(?:\([^)]*\))?\s+)?enum\s+)(\w+)', stripped)
        if m:
            enum_name = m.group(2)
            if name_filter and not re.search(name_filter, enum_name):
                continue
            end = _rust_find_brace_block(content, i, lines, offsets)
            for j in range(i, end):
                if j < len(lines):
                    ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

def _rust_find_enum_variants(content, lines, offsets):
    ranges = []
    in_enum = False
    enum_depth = 0
    for i, line in enumerate(lines):
        stripped = line.lstrip()
        if re.match(r'(?:pub\s+)?enum\s+\w', stripped):
            in_enum = True
            enum_depth = 0
        if in_enum:
            for c in line:
                if c == '{': enum_depth += 1
                elif c == '}':
                    enum_depth -= 1
                    if enum_depth == 0:
                        in_enum = False
            if in_enum and enum_depth == 1:
                # Look for variant definitions
                m = re.match(r'\s+(\w+)', line)
                if m and not stripped.startswith('//'):
                    ranges.append((offsets[i], offsets[i] + len(line)))
    return ranges

def _rust_find_impl(content, scope, lines, offsets):
    ranges = []
    for i, line in enumerate(lines):
        stripped = line.lstrip()
        is_impl = stripped.startswith('impl')
        if not is_impl:
            continue
        has_for = ' for ' in stripped
        if scope == 'impl-type' and has_for:
            continue
        if scope == 'impl-trait' and not has_for:
            continue
        end = _rust_find_brace_block(content, i, lines, offsets)
        for j in range(i, end):
            if j < len(lines):
                ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

def _rust_find_block(content, keyword, scope, lines, offsets):
    ranges = []
    name_filter = None
    if '~' in scope:
        name_filter = scope.split('~', 1)[1]

    for i, line in enumerate(lines):
        stripped = line.lstrip()
        m = re.match(rf'(?:pub(?:\([^)]*\))?\s+)?{keyword}\s+(\w+)', stripped)
        if m:
            block_name = m.group(1)
            if name_filter and not re.search(name_filter, block_name):
                continue
            if scope == 'mod-tests' and block_name != 'tests':
                continue
            end = _rust_find_brace_block(content, i, lines, offsets)
            for j in range(i, end):
                if j < len(lines):
                    ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

def _rust_find_unsafe(content, lines, offsets):
    ranges = []
    for i, line in enumerate(lines):
        if 'unsafe' in line:
            ranges.append((offsets[i], offsets[i] + len(line)))
    return ranges

def _find_rust_strings(content):
    ranges = []
    i = 0
    n = len(content)
    while i < n:
        # Raw strings r#"..."# or r"..."
        if content[i:i+2] == 'r#' or content[i:i+2] == 'r"':
            j = i + 1
            hashes = 0
            while j < n and content[j] == '#':
                hashes += 1
                j += 1
            if j < n and content[j] == '"':
                start = j + 1
                end_marker = '"' + '#' * hashes
                end_pos = content.find(end_marker, start)
                if end_pos >= 0:
                    ranges.append((start, end_pos))
                    i = end_pos + len(end_marker)
                else:
                    i = j + 1
            else:
                i = j
        elif content[i] == '"':
            start = i + 1
            j = start
            while j < n:
                if content[j] == '\\':
                    j += 2
                elif content[j] == '"':
                    break
                else:
                    j += 1
            ranges.append((start, j))
            i = j + 1
        elif content[i:i+2] == '//':
            while i < n and content[i] != '\n':
                i += 1
        elif content[i:i+2] == '/*':
            end = content.find('*/', i + 2)
            if end >= 0:
                i = end + 2
            else:
                break
        else:
            i += 1
    return ranges

def _go_scope(content, scope):
    lines = content.split('\n')
    ranges = []
    offsets = []
    off = 0
    for line in lines:
        offsets.append(off)
        off += len(line) + 1

    if scope == 'comments':
        for i, line in enumerate(lines):
            idx = line.find('//')
            if idx >= 0:
                ranges.append((offsets[i] + idx, offsets[i] + len(line)))
        return ranges

    elif scope == 'strings':
        return _find_go_strings(content)

    elif scope == 'imports':
        in_import = False
        for i, line in enumerate(lines):
