    return []

def _line_ranges(content: str, line_start: int, line_end: int) -> List[Tuple[int,int]]:
    """Get byte ranges for lines [line_start, line_end) (0-indexed)."""
    lines = content.split('\n')
    ranges = []
    offset = 0
    for i, line in enumerate(lines):
        line_len = len(line)
        if i >= line_start and i < line_end:
            ranges.append((offset, offset + line_len))
        offset += line_len + 1
    return ranges

def _find_indented_block(content: str, start_line: int) -> int:
    """Find the end line (exclusive) of an indented block starting after start_line."""
    lines = content.split('\n')
    if start_line >= len(lines):
        return start_line + 1
    # Find indent of first non-empty line after start_line
    base_indent = None
    for i in range(start_line + 1, len(lines)):
        stripped = lines[i]
        if stripped.strip():
            indent = len(stripped) - len(stripped.lstrip())
            base_indent = indent
            break
    if base_indent is None or base_indent == 0:
        return start_line + 1

    # Find end of block
    end = start_line + 1
    for i in range(start_line + 1, len(lines)):
        if lines[i].strip() == '':
            end = i + 1
            continue
        indent = len(lines[i]) - len(lines[i].lstrip())
        if indent >= base_indent:
            end = i + 1
        else:
            break
    return end

def _python_scope(content: str, scope: str) -> List[Tuple[int,int]]:
    lines = content.split('\n')
    ranges = []

    if scope == 'comments':
        # Python comment lines: # to end of line
        offset = 0
        for line in lines:
            idx = line.find('#')
            # Make sure '#' is not inside a string (simplified)
            if idx >= 0:
                ranges.append((offset + idx, offset + len(line)))
            offset += len(line) + 1
        return ranges

    elif scope == 'strings':
        # Find string literals (simplified: match quoted strings)
        return _find_python_strings(content)

    elif scope == 'doc-strings':
        return _find_python_docstrings(content)

    elif scope == 'imports':
        # Module names in import statements
        return _find_python_imports(content)

    elif scope in ('class', 'def', 'async-def', 'methods', 'class-methods',
                   'static-methods', 'with', 'try', 'lambda', 'globals',
                   'variable-identifiers', 'types', 'identifiers',
                   'function-names', 'function-calls'):
        return _find_python_block(content, scope)

    return []

def _find_python_strings(content: str) -> List[Tuple[int,int]]:
    """Find string literal content (inside quotes) in Python."""
    ranges = []
    i = 0
    n = len(content)
    while i < n:
        # Triple quote
        if content[i:i+3] in ('"""', "'''"):
            quote = content[i:i+3]
            start = i + 3
            end = content.find(quote, start)
            if end == -1:
                break
            ranges.append((start, end))
            i = end + 3
        elif content[i] in ('"', "'"):
            quote = content[i]
            start = i + 1
            j = start
            while j < n:
                if content[j] == '\\':
                    j += 2
                elif content[j] == quote:
                    break
                else:
                    j += 1
            ranges.append((start, j))
            i = j + 1
        elif content[i] == '#':
            # Skip to end of line
            while i < n and content[i] != '\n':
                i += 1
        else:
            i += 1
    return ranges

def _find_python_docstrings(content: str) -> List[Tuple[int,int]]:
    """Find docstring content in Python functions/classes."""
    ranges = []
