    if isinstance(scope, str) and scope.startswith('struct~'):
        name_filter = scope[7:]

    for i, line in enumerate(lines):
        stripped = line.lstrip()
        m = re.match(r'((?:pub(?:\([^)]*\))?\s+)?struct\s+)(\w+)', stripped)
        if m:
            struct_name = m.group(2)
            if name_filter and not re.search(name_filter, struct_name):
                continue
            # Check if this is a tuple struct (ends with ;) or block struct
            if '{' in line:
                end = _rust_find_brace_block(content, i, lines, offsets)
            else:
                end = i + 1
                for j in range(i, len(lines)):
                    if ';' in lines[j]:
                        end = j + 1
                        break
            for j in range(i, end):
                if j < len(lines):
                    ranges.append((offsets[j], offsets[j] + len(lines[j])))
    return ranges

