# ============================================================
# Core processing
# ============================================================

def make_replacement(replacement_template: str, match: re.Match) -> str:
    """Build replacement string from template and match object."""
    result = replacement_template
    # Handle ${NAME} style
    def replace_named_braced(mg):
        name = mg.group(1)
        try:
            v = match.group(name)
            return v if v is not None else ''
        except (IndexError, error):
            return mg.group(0)
    result = re.sub(r'\$\{(\w+)\}', replace_named_braced, result)
    # Handle $1, $2, etc.
    def replace_numbered(mg):
        n = int(mg.group(1))
        try:
            v = match.group(n)
            return v if v is not None else ''
        except IndexError:
            return ''
    result = re.sub(r'\$(\d+)', replace_numbered, result)
    # Handle $NAME (named groups without braces)
    def replace_named(mg):
        name = mg.group(1)
        try:
            v = match.group(name)
            return v if v is not None else ''
        except (IndexError, Exception) as e:
            raise ValueError(f"Undefined variable, unable to substitute: '{name}'") from e
    result = re.sub(r'\$([A-Za-z_]\w*)', replace_named, result)
    return result

def apply_action_to_text(text: str, args) -> str:
    """Apply all composable actions to text."""
    if args.upper: text = text.upper()
    if args.lower: text = text.lower()
    if args.titlecase: text = apply_titlecase(text)
    if args.normalize: text = apply_normalize(text)
    if args.german:
        if not args.invert:
            text = apply_german(text,
                prefer_original=args.german_prefer_original,
                naive=args.german_naive)
    if args.symbols:
        if args.invert:
            text = apply_symbols_inv(text)
        else:
            text = apply_symbols(text)
    return text

def squeeze_matches(text: str, pattern: re.Pattern) -> str:
    """Squeeze consecutive matches."""
    result = []
    prev_end = None
    last_pos = 0
    for m in pattern.finditer(text):
        if prev_end is not None and m.start() == prev_end:
            # Consecutive - skip
            prev_end = m.end()
        else:
            result.append(text[last_pos:m.start()])
            result.append(m.group())
            last_pos = m.end()
            prev_end = m.end()
    result.append(text[last_pos:])
    return ''.join(result)

def process_line(line: str, pattern: re.Pattern, args, 
                 in_scope_ranges=None) -> Tuple[str, List[Tuple[int,int]]]:
    """Process a single line and return (new_line, match_ranges).

    in_scope_ranges: if not None, list of (start,end) within the line that are in scope.
    """
    # Find what positions to work on
    if in_scope_ranges is not None:
        # Only process within scope ranges
        work_ranges = in_scope_ranges
    else:
        # Process entire line
        work_ranges = [(0, len(line))]

    # Find all regex matches within the work ranges
    all_matches = []
    for (rs, re_) in work_ranges:
        chunk = line[rs:re_]
        for m in pattern.finditer(chunk):
            all_matches.append((rs + m.start(), rs + m.end(), m))

    if args.delete:
        # Delete matched portions
        if not all_matches:
            return line, []
        result = []
        last = 0
        for (s, e, m) in all_matches:
            result.append(line[last:s])
            last = e
        result.append(line[last:])
        return ''.join(result), [(s, e) for s, e, _ in all_matches]

    if args.squeeze:
        # Squeeze consecutive matches within work ranges
        result = list(line)
        for (rs, re_) in work_ranges:
            chunk = line[rs:re_]
            new_chunk = squeeze_matches(chunk, pattern)
            result[rs:re_] = list(new_chunk)
        return ''.join(result), all_matches

    if not all_matches:
        return line, []

    # Apply replacement and/or other actions
    result = []
    last = 0
    new_matches = []

    for (s, e, m) in all_matches:
        result.append(line[last:s])
        matched_text = line[s:e]

        if args.replacement is not None:
            matched_text = make_replacement(args.replacement, m)

        matched_text = apply_action_to_text(matched_text, args)
