            if show_line_nums or only_matching:
                output_parts.append(format_output_line(source_name, line_num, matches, new_line, is_tty, show_line_nums))
            else:
                output_parts.append(new_line)

        else:
            # No actions, no search mode - just pass through with optional annotations
            matches = [(m.start(), m.end()) for m in pattern.finditer(line)]
            if matches:
                had_match = True

            if only_matching and not matches:
                continue

            if show_line_nums or only_matching:
                output_parts.append(format_output_line(source_name, line_num, matches, line, is_tty, show_line_nums))
            else:
                output_parts.append(line)

    result = '\n'.join(output_parts)
    if has_trailing_nl or (output_parts and not result.endswith('\n')):
        if content.endswith('\n'):
