# ============================================================
# Core processing
# ============================================================

def make_replacement(replacement_template: str, match: re.Match) -> str:
    """Build replacement string from template and match object."""
    result = replacement_template
    # Handle ${NAME} style
    def replace_named_braced(mg):
        name = mg.group(1)
        try:
            v = match.group(name)
            return v if v is not None else ''
        except (IndexError, error):
            return mg.group(0)
    result = re.sub(r'\$\{(\w+)\}', replace_named_braced, result)
    # Handle $1, $2, etc.
    def replace_numbered(mg):
        n = int(mg.group(1))
        try:
            v = match.group(n)
            return v if v is not None else ''
        except IndexError:
            return ''
    result = re.sub(r'\$(\d+)', replace_numbered, result)
    # Handle $NAME (named groups without braces)
    def replace_named(mg):
        name = mg.group(1)
        try:
            v = match.group(name)
            return v if v is not None else ''
        except (IndexError, Exception) as e:
            raise ValueError(f"Undefined variable, unable to substitute: '{name}'") from e
    result = re.sub(r'\$([A-Za-z_]\w*)', replace_named, result)
    return result

def apply_action_to_text(text: str, args) -> str:
    """Apply all composable actions to text."""
    if args.upper: text = text.upper()
    if args.lower: text = text.lower()
    if args.titlecase: text = apply_titlecase(text)
    if args.normalize: text = apply_normalize(text)
    if args.german:
        if not args.invert:
            text = apply_german(text,
                prefer_original=args.german_prefer_original,
                naive=args.german_naive)
    if args.symbols:
        if args.invert:
            text = apply_symbols_inv(text)
        else:
            text = apply_symbols(text)
    return text

def squeeze_matches(text: str, pattern: re.Pattern) -> str:
    """Squeeze consecutive matches."""
    result = []
    prev_end = None
    last_pos = 0
    for m in pattern.finditer(text):
        if prev_end is not None and m.start() == prev_end:
            # Consecutive - skip
            prev_end = m.end()
        else:
            result.append(text[last_pos:m.start()])
            result.append(m.group())
            last_pos = m.end()
            prev_end = m.end()
    result.append(text[last_pos:])
    return ''.join(result)

def process_line(line: str, pattern: re.Pattern, args, 
                 in_scope_ranges=None) -> Tuple[str, List[Tuple[int,int]]]:
    """Process a single line and return (new_line, match_ranges).

    in_scope_ranges: if not None, list of (start,end) within the line that are in scope.
    """
    # Find what positions to work on
    if in_scope_ranges is not None:
        # Only process within scope ranges
        work_ranges = in_scope_ranges
    else:
        # Process entire line
        work_ranges = [(0, len(line))]

    # Find all regex matches within the work ranges
    all_matches = []
    for (rs, re_) in work_ranges:
        chunk = line[rs:re_]
        for m in pattern.finditer(chunk):
            all_matches.append((rs + m.start(), rs + m.end(), m))

    if args.delete:
        # Delete matched portions
        if not all_matches:
            return line, []
        result = []
        last = 0
        for (s, e, m) in all_matches:
            result.append(line[last:s])
            last = e
        result.append(line[last:])
        return ''.join(result), [(s, e) for s, e, _ in all_matches]

    if args.squeeze:
        # Squeeze consecutive matches within work ranges
        result = list(line)
        for (rs, re_) in work_ranges:
            chunk = line[rs:re_]
            new_chunk = squeeze_matches(chunk, pattern)
            result[rs:re_] = list(new_chunk)
        return ''.join(result), all_matches

    if not all_matches:
        return line, []

    # Apply replacement and/or other actions
    result = []
    last = 0
    new_matches = []

    for (s, e, m) in all_matches:
        result.append(line[last:s])
        matched_text = line[s:e]

        if args.replacement is not None:
            matched_text = make_replacement(args.replacement, m)

        matched_text = apply_action_to_text(matched_text, args)
        new_start = sum(len(x) for x in result)
        result.append(matched_text)
        new_end = sum(len(x) for x in result)
        new_matches.append((s, e))  # original match positions for display
        last = e

    result.append(line[last:])
    return ''.join(result), new_matches

def format_output_line(source: str, line_num: int, match_ranges: List[Tuple[int,int]],
                       line_content: str, is_tty: bool, show_line_nums: bool) -> str:
    """Format a line for output in search/annotated mode."""
    range_str = ';'.join(f'{s}-{e}' for s,e in match_ranges) if match_ranges else ''

    if is_tty:
        if show_line_nums:
            return f'{line_num}:{line_content}'
        else:
            return line_content
    else:
        if show_line_nums:
            return f'{source}:{line_num}:{range_str}:{line_content}'
        else:
            return f'{source}:{range_str}:{line_content}'

def process_content(content: str, pattern: re.Pattern, args,
                    lang_byte_ranges: Optional[List[Tuple[int,int]]],
                    source_name: str, is_tty: bool) -> Tuple[str, bool]:
    """
    Process file/stdin content. Returns (output, had_any_match).
    """
    has_actions = (args.upper or args.lower or args.titlecase or args.normalize or
                   args.german or args.symbols or args.replacement is not None)
    has_standalone = args.delete or args.squeeze
    has_lang = lang_byte_ranges is not None
    search_mode = has_lang and not has_actions and not has_standalone
    show_line_nums = args.line_numbers
    only_matching = args.only_matching

    lines = content.split('\n')
    has_trailing_nl = content.endswith('\n')
    if has_trailing_nl and lines and lines[-1] == '':
        lines = lines[:-1]

    output_parts = []
    had_match = False

    # Build per-line scope info
    line_offsets = []
    off = 0
    for line in lines:
        line_offsets.append(off)
        off += len(line) + 1

    for line_idx, line in enumerate(lines):
        line_num = line_idx + 1
        line_start = line_offsets[line_idx]
        line_end = line_start + len(line)

        # Find scope ranges for this line
        in_scope = True
        scope_ranges_for_line = None

        if lang_byte_ranges is not None:
            relevant = []
            for (bs, be) in lang_byte_ranges:
                if bs < line_end and be > line_start:
                    cs = max(bs, line_start) - line_start
                    ce = min(be, line_end) - line_start
                    if cs < ce:
                        relevant.append((cs, ce))
            if relevant:
                scope_ranges_for_line = relevant
                in_scope = True
            else:
                in_scope = False

        if not in_scope:
            # Line not in language scope
            if search_mode:
                continue  # Skip in search mode
            elif has_actions or has_standalone:
                # Output unchanged
                if show_line_nums:
                    output_parts.append(format_output_line(source_name, line_num, [], line, is_tty, show_line_nums))
                else:
                    output_parts.append(line)
            elif show_line_nums:
                output_parts.append(format_output_line(source_name, line_num, [], line, is_tty, show_line_nums))
            else:
                output_parts.append(line)
            continue

        if search_mode:
            # Find regex matches within scope
            matches = []
            if scope_ranges_for_line is not None:
                # Default scope (.*) means show whole line
                if pattern.pattern in ('.*', '.+', '.*?'):
                    # Show entire in-scope content
                    matches = [(cs, ce) for cs, ce in scope_ranges_for_line]
                    had_match = True
                    # For display, use first match range? No, use full line range
                    # Actually in tree-sitter search mode, range is full line
                    full_range = [(0, len(line))]
                    output_parts.append(format_output_line(source_name, line_num, full_range, line, is_tty, True))
                else:
                    for (rs, re_) in scope_ranges_for_line:
                        chunk = line[rs:re_]
                        for m in pattern.finditer(chunk):
                            matches.append((rs + m.start(), rs + m.end()))
                    if matches:
                        had_match = True
                        output_parts.append(format_output_line(source_name, line_num, matches, line, is_tty, True))
            else:
                matches = [(m.start(), m.end()) for m in pattern.finditer(line)]
                if matches:
                    had_match = True
                    output_parts.append(format_output_line(source_name, line_num, matches, line, is_tty, True))

        elif has_actions or has_standalone:
            new_line, matches = process_line(line, pattern, args, scope_ranges_for_line)
            if matches:
                had_match = True

            if only_matching and not matches:
                continue

            if show_line_nums or only_matching:
                output_parts.append(format_output_line(source_name, line_num, matches, new_line, is_tty, show_line_nums))
            else:
                output_parts.append(new_line)

        else:
            # No actions, no search mode - just pass through with optional annotations
            matches = [(m.start(), m.end()) for m in pattern.finditer(line)]
            if matches:
                had_match = True

            if only_matching and not matches:
                continue

            if show_line_nums or only_matching:
                output_parts.append(format_output_line(source_name, line_num, matches, line, is_tty, show_line_nums))
            else:
                output_parts.append(line)

    result = '\n'.join(output_parts)
    if has_trailing_nl or (output_parts and not result.endswith('\n')):
        if content.endswith('\n'):
            result += '\n'

    return result, had_match

